    def _prepare_image_flow_condition(
        self,
        z: torch.Tensor,
    ) -> torch.Tensor:
        z = z.to(
            device=self.image_flow_condition_proj.weight.device,
            dtype=self.image_flow_condition_proj.weight.dtype,
        )
        return self.image_flow_condition_proj(z)

    def _uses_backbone_x0_flow_content_condition(self) -> bool:
        """Whether the contextual head uses split XT/X0 AdaLN conditions."""

        return type(self.image_flow_head) is X0ContentFlowLoss

    def _zero_image_module_loss(
        self,
        hidden_states: torch.Tensor,
    ) -> torch.Tensor:
        """Return zero while keeping skipped image modules in the train graph."""

        zero = hidden_states.float().sum() * 0.0
        for module in (self.image_flow_condition_proj, self.image_flow_head):
            for parameter in module.parameters():
                if parameter.requires_grad and parameter.numel() > 0:
                    zero = zero + parameter.reshape(-1)[0].float() * 0.0
