            context_mask=context_mask,
            content_attention_mask=content_attention_mask,
            query_positions=query_positions,
            context_positions=context_positions,
            context_conditions=context_conditions,
            latent_mixer_cache=latent_mixer_cache,
            latent_mixer_cache_is_paired=latent_mixer_cache_is_paired,
            pending_context_latents=pending_context_latents,
            pending_context_conditions=pending_context_conditions,
            pending_context_positions=pending_context_positions,
            context_prepared=context_prepared,
            initial_noise=initial_noise,
